inline void north(G2NaturalDriver& r){r.reception();for(const auto& id:{"m159-e5","m164-e2","m166-e21","m170-e2","m169-e5"}){r.actObject(id);}r.actAt({13,5},Direction::Up);r.tick(key());r.settle();need(r.game.mapId()==186,"05 natural vent absent");r.actObject("m186-e4");}
