inline void toHeat(G2NaturalDriver& r){north(r);r.actObject("m169-e7");lift(r,1);for(const auto& id:{"m177-e4","m178-e3","m179-e3","m180-e20"}){r.actObject(id);}need(r.game.mapId()==181,"Natural heat room entry absent");}
