inline void fight(G2NaturalDriver& r,const std::string& id){
 auto& g=r.game;const auto& d=g.content().enemies.at(id);need(g.mapId()==d.map&&(!d.rules.contains("activation_fact")||g.session().flag(d.rules.at("activation_fact"))),"05 natural target inactive");const int threshold=d.rules.value("behavior",std::string{})=="chimera"?250:d.rules.value("death_damage_threshold",100);int fired=0,wait=0,readyTick=0;const bool adaptive=g.session().variable(635)==1||g.session().difficulty()!="normal";bool sawFall=false;const auto target=findCharacter(g.world(),id).motion.tile();bool reachable=false;for(auto side:{Direction::Down,Direction::Up,Direction::Right,Direction::Left}){const auto adjacent=adjacentTile(target,side);reachable|=g.world().player().motion.tile()==adjacent||next(g.world(),adjacent).has_value();}need(reachable,"05 target lies in another source partition: "+id);
 for(int n=0;n<2200&&!g.session().flag(d.deadFlag);++n){auto& s=g.session();need(s.hp()>0&&g.mode()==ApplicationMode::Playing,"05 natural battle failed");if(adaptive&&s.hp()<60&&r.healingItem()!=0&&g.foreground()==ForegroundKind::None&&s.flag(1)&&!s.flag(10)&&!s.flag(45)){r.lowerForMenu(readyTick);need(r.healTo(100),"Adaptive heat actual healing absent");continue;}InputFrame in;const int weapon=s.equipped(1),rounds=s.magazine(weapon);int damage=0;for(const auto& enemy:g.enemyStates()){if(enemy.id==id){damage=enemy.damage;sawFall|=enemy.sourceState==100&&enemy.damage<threshold;}}
  if(g.foreground()!=ForegroundKind::None||g.dialogue().active()){if(n%8==0){in=key();}}
  else if(s.flag(10)||s.flag(45)||!s.flag(1)){if(n%2==0){in=key(n%4==0?InputAction::Up:InputAction::Left);}}
  else if(damage>=threshold){}
  else if(!g.raised()){in=key(InputAction::Weapon);}
  else{const auto p=g.world().player().motion.tile(),t=findCharacter(g.world(),id).motion.tile();const int dx=t.x-p.x,dy=t.y-p.y;const auto face=std::abs(dx)>std::abs(dy)?(dx>0?Direction::Right:Direction::Left):(dy>0?Direction::Down:Direction::Up);
   if((dx&&dy)||std::abs(dx)+std::abs(dy)>4){for(auto side:{Direction::Down,Direction::Up,Direction::Right,Direction::Left}){if(auto step=next(g.world(),adjacentTile(t,side))){in.movement=step;break;}}}
   else if(g.world().player().motion.facing()!=face){in.buttons[int(InputAction::Weapon)].held=true;in.movement=face;}
   else if(wait==0){if(rounds==0&&!s.hasReserve()){if(adaptive){r.lowerForMenu(readyTick);}else{r.lower();}if(adaptive){r.equipAvailable({20,15,19,21});}else{r.equip(21);need(s.magazine(21)>0||s.hasReserve(),"05 actual second weapon exhausted");}continue;}in=key(InputAction::Attack);wait=36;}
  }
  if(wait>0){--wait;}r.tick(in);const int used=std::max(0,rounds-s.magazine(weapon));fired+=used;if(used){readyTick=r.ticks+r.fireRecoveryTicks(weapon);}if(n%200==0){const auto p=g.world().player().motion.tile(),t=findCharacter(g.world(),id).motion.tile();std::cout<<"05 fight "<<id<<" n="<<n<<" p="<<p.x<<","<<p.y<<" e="<<t.x<<","<<t.y<<" dmg="<<damage<<" hp="<<s.hp()<<" mag="<<s.magazine(weapon)<<" corr="<<s.conditions().corroded<<'\n';}
 }
 need(g.session().flag(d.deadFlag)&&fired>0,"05 natural battle stalled before source death");if(adaptive){r.lowerForMenu(readyTick);}else{r.lower();}if(g.session().hp()<80&&g.session().count(5)>0){r.item(5);}std::cout<<"05 real kill "<<id<<" shots="<<fired<<" source-fall="<<sawFall<<" HP="<<g.session().hp()<<'\n';
}
